/**
 * The value used on the `upperBound` field of a tier to describe a tier without an upper limit.
 */
export const infiniteUpperBound = 'inf';

/**
 * @author Paigo
 *
 * @Class
 * A single volume based pricing tier of a dimension.
 * <br><br>
 * Tiers allow a dimension to be billed at different unit prices depending on the amount of usage which was consumed.
 * All numeric values are represented as strings in order to avoid any loss of precision.
 */
export class DimensionTier {
    /**
     * The position of the tier relative to the other tiers of the dimension.
     * Tiers are always evaluated in ascending numerical order of this field.
     * <br><br>
     * Example: `"1"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierPosition',
        type: String,
        example: '1',
        required: true,
        description:
            'The position of the tier relative to the other tiers of the dimension, represented as a numeric string.',
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of the tier in terms of usage.
     * The lower bound of a tier is the upper bound of the previous tier, the first tier starts at 0.
     * The last tier may use the value `"inf"` to describe a tier without an upper limit.
     * <br><br>
     * Example: `"1000"`, `"inf"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'upperBound',
        type: String,
        example: '1000',
        required: true,
        description:
            'The inclusive upper bound of the tier, a numeric string or "inf". Must be a multiple of the usageIncrement of the dimension.',
    })
    public upperBound: string;

    /**
     * An optional friendly name for the tier, when set it is appended to the name of the invoice line item of the tier.
     * <br><br>
     * Example: `"First 1000 requests"`
     */
    @IsOptional()
    @IsString()
    @ApiProperty({
        name: 'tierName',
        type: String,
        example: 'First 1000 requests',
        required: false,
        description: 'An optional friendly name of the tier, appended to the invoice line item name of the tier.',
    })
    public tierName?: string;

    /**
     * The unit price of the usage which falls inside of this tier.
     * The field is required for every tier except the first one, a first tier without a unit price is a free tier.
     * <br><br>
     * Example: `"0.05"`
     */
    @IsOptional()
    @IsString()
    @ApiProperty({
        name: 'unitPrice',
        type: String,
        example: '0.05',
        required: false,
        description:
            'The unit price for the usage within the tier. Required for every tier except the first tier, an omitted price on the first tier describes a free tier.',
    })
    public unitPrice?: string;

    constructor(tier?: DimensionTier) {
        if (tier) {
            const { tierPosition, upperBound, tierName, unitPrice } = tier;
            this.tierPosition = tierPosition;
            this.upperBound = upperBound;
            if (tierName !== undefined) {
                this.tierName = tierName;
            }
            if (unitPrice !== undefined) {
                this.unitPrice = unitPrice;
            }
        }
    }
}

