import { BadRequestException, Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, DimensionTier, infiniteUpperBound, overageAllowedEnum } from './create-dimension.dto.js';

/**
 * The maximum number of decimal places any price field within Paigo accepts.
 */
const MAX_PRICE_DECIMAL_PLACES = 8;

/**
 * A subset of a dimension containing every field which participates in the validation of the tiers of the dimension.
 */
export type TieredDimensionLike = {
    tiers?: DimensionTier[] | null;
    usageIncrement?: string | number;
    usageEntitlement?: number | 'inf' | null;
    consumptionPrice?: string | null;
    overageAllowed?: overageAllowedEnum | string | boolean | null;
};

/**
 * Determines if a given upperBound describes an unlimited (infinite) tier.
 */
export const isInfiniteBound = (upperBound?: string | null): boolean =>
    typeof upperBound === 'string' && upperBound.trim().toLowerCase() === infiniteUpperBound;

const isNumericString = (value: unknown): boolean =>
    typeof value === 'string' &&
    value.trim() !== '' &&
    // Type coersion is needed here since the values are numeric strings
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    !isNaN(value) &&
    !isNaN(parseFloat(value));

const decimalPlaces = (value: string): number => value.split('.')[1]?.length ?? 0;

/**
 * Returns the numeric value of the upperBound of a tier, `Infinity` is returned for the `"inf"` upperBound.
 */
export const tierUpperBoundToNumber = (upperBound?: string | null): number =>
    isInfiniteBound(upperBound) ? Infinity : Number(upperBound);

/**
 * Sorts the tiers of a dimension in ascending numerical order of their tierPosition.
 * The input array is never mutated.
 */
export const sortTiersByPosition = (tiers: DimensionTier[] = []): DimensionTier[] =>
    [...tiers].sort((firstTier, secondTier) => Number(firstTier?.tierPosition) - Number(secondTier?.tierPosition));

/**
 * Collects every validation error of the tiers of a dimension.
 * An empty array is returned when the tiers are valid, or when the dimension does not use tiers at all.
 */
export const collectTierValidationErrors = ({
    tiers,
    usageIncrement,
    usageEntitlement,
    consumptionPrice,
    overageAllowed,
}: TieredDimensionLike): string[] => {
    if (tiers === undefined || tiers === null) {
        // Dimensions without tiers, and dimensions clearing their tiers with null, are always valid here.
        return [];
    }
    if (!Array.isArray(tiers)) {
        return ['tiers: The tiers field must be an array of tier objects'];
    }
    if (!tiers.length) {
        return ['tiers: At least one tier must be provided when the tiers field is set. Pass null to remove the tiers'];
    }
    const errors: string[] = [];

    // Tiered dimensions are mutually exclusive with entitlements, a single consumption price and overage.
    if (usageEntitlement !== undefined && usageEntitlement !== null) {
        errors.push('tiers: Tiers cannot be combined with usageEntitlement');
    }
    if (consumptionPrice !== undefined && consumptionPrice !== null) {
        errors.push('tiers: Tiers cannot be combined with consumptionPrice');
    }
    if (overageAllowed === overageAllowedEnum.true || overageAllowed === true) {
        errors.push('tiers: Tiers cannot be combined with overageAllowed set to true');
    }

    // Validate the shape of every single tier before looking at the tiers as a whole.
    const shapeErrors: string[] = [];
    tiers.forEach((tier) => {
        if (!tier || typeof tier !== 'object') {
            shapeErrors.push('tiers: Every tier must be an object containing a tierPosition and an upperBound');
            return;
        }
        const { tierPosition, upperBound, tierName, unitPrice } = tier;
        if (!isNumericString(tierPosition) || !Number.isInteger(Number(tierPosition)) || Number(tierPosition) < 0) {
            shapeErrors.push(
                `tiers: tierPosition: ${tierPosition} must be a numeric string containing a non negative integer`,
            );
        }
        if (!isInfiniteBound(upperBound)) {
            if (!isNumericString(upperBound)) {
                shapeErrors.push(
                    `tiers: upperBound: ${upperBound} must be a numeric string or the string "${infiniteUpperBound}"`,
                );
            } else if (Number(upperBound) <= 0) {
                shapeErrors.push(`tiers: upperBound: ${upperBound} must be greater than 0`);
            }
        }
        if (tierName !== undefined && tierName !== null && typeof tierName !== 'string') {
            shapeErrors.push(`tiers: tierName: ${tierName} must be a string`);
        }
        if (unitPrice !== undefined && unitPrice !== null) {
            if (!isNumericString(unitPrice)) {
                shapeErrors.push(`tiers: unitPrice: ${unitPrice} must be a numeric string`);
            } else if (Number(unitPrice) < 0) {
                shapeErrors.push(`tiers: unitPrice: ${unitPrice} cannot be negative`);
            } else if (decimalPlaces(unitPrice) > MAX_PRICE_DECIMAL_PLACES) {
                shapeErrors.push(
                    `tiers: unitPrice: ${unitPrice} cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after the decimal place`,
                );
            }
        }
    });
    if (shapeErrors.length) {
        // Without well formed tiers the bounds cannot be compared with each other.
        return [...errors, ...shapeErrors];
    }

    const positions = tiers.map(({ tierPosition }) => Number(tierPosition));
    if (new Set(positions).size !== positions.length) {
        errors.push('tiers: Every tierPosition must be unique');
    }

    const sortedTiers = sortTiersByPosition(tiers);

    sortedTiers.forEach((tier, index) => {
        const { tierPosition, upperBound, unitPrice } = tier;
        // Only the very last tier is allowed to be unbounded.
        if (isInfiniteBound(upperBound) && index !== sortedTiers.length - 1) {
            errors.push(
                `tiers: An upperBound of "${infiniteUpperBound}" is only allowed on the last tier. tierPosition: ${tierPosition} is not the last tier`,
            );
        }
        // Every tier but the first one has to be priced, an unpriced first tier is a free tier.
        if (index > 0 && (unitPrice === undefined || unitPrice === null)) {
            errors.push(
                `tiers: unitPrice is required for every tier after the first tier. tierPosition: ${tierPosition} is missing a unitPrice`,
            );
        }
    });

    let previousUpperBound = 0;
    sortedTiers.forEach(({ tierPosition, upperBound }) => {
        const numericUpperBound = tierUpperBoundToNumber(upperBound);
        if (numericUpperBound <= previousUpperBound) {
            errors.push(
                `tiers: The upperBound of every tier must be greater than the upperBound of the previous tier. tierPosition: ${tierPosition} with upperBound: ${upperBound} overlaps with the previous tier`,
            );
        }
        previousUpperBound = numericUpperBound;
    });

    const numericUsageIncrement = Number(usageIncrement);
    if (
        usageIncrement !== undefined &&
        usageIncrement !== null &&
        Number.isFinite(numericUsageIncrement) &&
        numericUsageIncrement > 0
    ) {
        sortedTiers.forEach(({ tierPosition, upperBound }) => {
            if (isInfiniteBound(upperBound)) {
                return;
            }
            if (Number(upperBound) % numericUsageIncrement !== 0) {
                errors.push(
                    `tiers: The upperBound of every tier must align with the usageIncrement: ${usageIncrement}. tierPosition: ${tierPosition} with upperBound: ${upperBound} is not a multiple of the usageIncrement`,
                );
            }
        });
    }

    return errors;
};

/**
 * Determines if the tiers of a dimension are valid.
 */
export const tiersAreValid = (dimension: TieredDimensionLike): boolean =>
    collectTierValidationErrors(dimension).length === 0;

/**
 * Validates the tiers of a dimension, throwing a BadRequestException listing every problem found.
 */
export const validateTiersOrThrow = (dimension: TieredDimensionLike): void => {
    const errors = collectTierValidationErrors(dimension);
    if (errors.length) {
        throw new BadRequestException(errors);
    }
};

@ValidatorConstraint({ name: 'ValidateTiers', async: false })
@Injectable()
export class ValidateTiersRule implements ValidatorConstraintInterface {
    validate(tiers: DimensionTier[], args: ValidationArguments) {
        const dimension = (args?.object ?? {}) as CreateDimensionDto;
        return collectTierValidationErrors({ ...dimension, tiers }).length === 0;
    }

    defaultMessage(args: ValidationArguments) {
        const dimension = (args?.object ?? {}) as CreateDimensionDto;
        return collectTierValidationErrors(dimension).join(' | ');
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidateTiersRule,
        });
    };
}

