/**
 * Allocates the total usage of a dimension across the volume based pricing tiers of the dimension.
 * <br><br>
 * The tiers are always evaluated in ascending numerical order of their tierPosition.
 * The bounds of a tier are inclusive, meaning a tier with an upperBound of `"1000"` covers every unit of usage
 * from the upper bound of the previous tier up to and including the 1000th unit.
 * Only the tiers which were actually consumed are returned.
 */
public static allocateUsageToTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number;
    tiers: DimensionTier[];
}): TierUsageAllocation[] {
    if (!Array.isArray(tiers) || !tiers.length) {
        return [];
    }
    const usage = Number(totalUsage);
    if (!Number.isFinite(usage) || usage <= 0) {
        return [];
    }
    const allocations: TierUsageAllocation[] = [];
    let lowerBound = 0;
    for (const tier of Billing.sortTiers(tiers)) {
        const upperBound = tierUpperBoundToNumber(tier?.upperBound);
        const allocatedUsage = Math.min(usage, upperBound) - lowerBound;
        if (allocatedUsage > 0) {
            allocations.push({ tier, usage: allocatedUsage, lowerBound, upperBound });
        }
        lowerBound = upperBound;
        if (usage <= upperBound) {
            break;
        }
    }
    return allocations;
}

