import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    CreateDimensionDto,
    DimensionTier,
    overageAllowedEnum,
    roundingEnum,
} from './create-dimension.dto.js';
import { UpdateDimensionDto } from './update-dimension.dto.js';
import { collectTierValidationErrors, sortTiersByPosition, tiersAreValid, validateTiersOrThrow } from './tiersValidator.js';

const validTiers: DimensionTier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000' },
    { tierPosition: '2', upperBound: '5000', tierName: 'Next 4000', unitPrice: '0.05' },
    { tierPosition: '3', upperBound: 'inf', tierName: 'Everything else', unitPrice: '0.03' },
];

const baseDimension = () => ({
    dimensionName: 'Requests',
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
    aggregationInterval: aggregationInterval.day,
    aggregationMethod: aggregationMethod.sum,
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
});

describe('Dimension tiers validation', () => {
    test('A dimension without tiers is never rejected by the tier validation', () => {
        expect(collectTierValidationErrors({ usageIncrement: '1' })).toEqual([]);
        expect(collectTierValidationErrors({ tiers: undefined, consumptionPrice: '2' })).toEqual([]);
        // Passing null clears the tiers of a dimension and must always be accepted
        expect(collectTierValidationErrors({ tiers: null, consumptionPrice: '2' })).toEqual([]);
        expect(() => validateTiersOrThrow({ tiers: null, consumptionPrice: '2' })).not.toThrow();
    });

    test('A well formed list of tiers is valid', () => {
        expect(collectTierValidationErrors({ tiers: validTiers, usageIncrement: '1' })).toEqual([]);
        expect(tiersAreValid({ tiers: validTiers, usageIncrement: '1' })).toBe(true);
        expect(() => validateTiersOrThrow({ tiers: validTiers, usageIncrement: '1' })).not.toThrow();
    });

    test('An empty list of tiers is rejected', () => {
        expect(collectTierValidationErrors({ tiers: [], usageIncrement: '1' }).length).toBeGreaterThan(0);
    });

    test('Upper bounds must increase without overlapping', () => {
        const errors = collectTierValidationErrors({
            tiers: [
                { tierPosition: '1', upperBound: '1000' },
                { tierPosition: '2', upperBound: '1000', unitPrice: '1' },
            ],
            usageIncrement: '1',
        });
        expect(errors.length).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: '10', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
    });

    test('Upper bounds must align with the usage increment of the dimension', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '24',
            }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1008' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '24',
            }),
        ).toEqual([]);
    });

    test('An infinite upper bound is only allowed on the last tier', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: 'inf' },
                    { tierPosition: '2', upperBound: '5000', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
    });

    test('Every tier after the first one requires a unit price, an unpriced first tier is a free tier', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.01' },
                ],
                usageIncrement: '1',
            }),
        ).toEqual([]);
    });

    test('Tier positions must be unique numeric strings', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: 'first', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
    });

    test('Unit prices cannot exceed 8 digits of precision and cannot be negative', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.000000004' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '-1' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
                usageIncrement: '1',
            }).length,
        ).toBeGreaterThan(0);
    });

    test('Tiers are mutually exclusive with entitlements, consumption price and overage', () => {
        expect(
            collectTierValidationErrors({ tiers: validTiers, usageIncrement: '1', usageEntitlement: 100 }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({ tiers: validTiers, usageIncrement: '1', consumptionPrice: '2' }).length,
        ).toBeGreaterThan(0);
        expect(
            collectTierValidationErrors({
                tiers: validTiers,
                usageIncrement: '1',
                overageAllowed: overageAllowedEnum.true,
            }).length,
        ).toBeGreaterThan(0);
        // Overage explicitly turned off does not conflict with tiers
        expect(
            collectTierValidationErrors({
                tiers: validTiers,
                usageIncrement: '1',
                overageAllowed: overageAllowedEnum.false,
            }),
        ).toEqual([]);
    });

    test('Tiers are sorted by the numerical value of their tier position', () => {
        const sorted = sortTiersByPosition([
            { tierPosition: '10', upperBound: 'inf', unitPrice: '1' },
            { tierPosition: '2', upperBound: '5000', unitPrice: '2' },
            { tierPosition: '1', upperBound: '1000' },
        ]);
        expect(sorted.map(({ tierPosition }) => tierPosition)).toEqual(['1', '2', '10']);
    });

    test('Out of order tiers are validated in their sorted order', () => {
        expect(
            collectTierValidationErrors({
                tiers: [
                    { tierPosition: '10', upperBound: 'inf', unitPrice: '1' },
                    { tierPosition: '2', upperBound: '5000', unitPrice: '2' },
                    { tierPosition: '1', upperBound: '1000' },
                ],
                usageIncrement: '1',
            }),
        ).toEqual([]);
    });

    test('A tiered dimension passes the DTO validation', async () => {
        const dto = plainToInstance(CreateDimensionDto, { ...baseDimension(), tiers: validTiers });
        expect(await validate(dto)).toEqual([]);
    });

    test('A tiered dimension with a consumption price fails the DTO validation', async () => {
        const dto = plainToInstance(CreateDimensionDto, {
            ...baseDimension(),
            consumptionPrice: '2',
            tiers: validTiers,
        });
        expect((await validate(dto)).length).toBeGreaterThan(0);
    });

    test('A tiered dimension with invalid bounds fails the DTO validation', async () => {
        const dto = plainToInstance(CreateDimensionDto, {
            ...baseDimension(),
            tiers: [
                { tierPosition: '1', upperBound: '1000' },
                { tierPosition: '2', upperBound: '100', unitPrice: '1' },
            ],
        });
        expect((await validate(dto)).length).toBeGreaterThan(0);
    });

    test('Removing the tiers of a dimension with null passes the DTO validation', async () => {
        const dto = plainToInstance(UpdateDimensionDto, { tiers: null });
        expect(await validate(dto)).toEqual([]);
    });

    test('Non tiered dimensions keep their existing validation behaviour', async () => {
        const withoutPrice = plainToInstance(CreateDimensionDto, baseDimension());
        expect((await validate(withoutPrice)).length).toBeGreaterThan(0);
        const withPrice = plainToInstance(CreateDimensionDto, { ...baseDimension(), consumptionPrice: '0.4' });
        expect(await validate(withPrice)).toEqual([]);
    });
});

import { Point } from '@influxdata/influxdb-client';
import { createMock } from '@golevelup/ts-jest';
import { Test, TestingModule } from '@nestjs/testing';
import { InfluxService } from '../influx/influx.service.js';
import { DimensionsService } from './dimensions.service.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    CreateDimensionDto,
    DimensionTier,
    roundingEnum,
} from './dto/create-dimension.dto.js';
import { DimensionEntity } from './entities/dimensions.entity.js';

const tiers: DimensionTier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000' },
    { tierPosition: '2', upperBound: '5000', tierName: 'Next 4000', unitPrice: '0.05' },
    { tierPosition: '3', upperBound: 'inf', unitPrice: '0.03' },
];

const tieredDimensionDto = () =>
    ({
        dimensionName: 'Requests',
        usageIncrement: '1',
        rounding: roundingEnum.ceiling,
        aggregationInterval: aggregationInterval.day,
        aggregationMethod: aggregationMethod.sum,
        consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
        businessID: 'fakeBusinessID',
        tiers,
    }) as unknown as CreateDimensionDto;

describe('Dimension tiers persistence', () => {
    let service: DimensionsService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [DimensionsService] })
            .useMocker(createMock)
            .compile();
        service = module.get<DimensionsService>(DimensionsService);
    });

    test('The tiers of a dimension are carried over to the entity and written to the ledger', () => {
        const input = service.transformDtoToEntityInput(tieredDimensionDto(), 'fakeDimensionId');
        expect(input.numerical.tiers).toEqual(tiers);
        const point = DimensionEntity.transformer(
            new DimensionEntity(input),
            //eslint-disable-next-line
            //@ts-ignore
            { getPoint: (measurement: string) => new Point(measurement) } as InfluxService,
        );
        expect(point.toLineProtocol()).toContain('tiers=');
        expect(point.toLineProtocol()).toContain('tierPosition');
    });

    test('Passing null for the tiers removes them from the dimension', () => {
        const input = service.transformDtoToEntityInput(
            { ...tieredDimensionDto(), tiers: null } as unknown as CreateDimensionDto,
            'fakeDimensionId',
        );
        expect(input.numerical.tiers).toBeUndefined();
        const point = DimensionEntity.transformer(
            new DimensionEntity(input),
            //eslint-disable-next-line
            //@ts-ignore
            { getPoint: (measurement: string) => new Point(measurement) } as InfluxService,
        );
        expect(point.toLineProtocol()).not.toContain('tiers=');
    });

    test('The tiers read back from the ledger are the exact same tier objects', () => {
        const entity = DimensionEntity.dbModelToEntity({
            _value: 'Requests',
            businessID: 'fakeBusinessID',
            dimensionId: 'fakeDimensionId',
            typeofDimension: 'numerical',
            dimensionUnit: countBasedUnits['count-based'],
            dimensionUnitType: 'count',
            aggregationInterval: aggregationInterval.day,
            aggregationMethod: aggregationMethod.sum,
            priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf' }]),
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
            tiers: JSON.stringify(tiers),
        });
        expect(entity.numerical.tiers).toEqual(tiers);
        const dto = new CreateDimensionDto(entity);
        expect(dto.tiers).toEqual(tiers);
        expect(dto.consumptionPrice).toBeUndefined();
        expect(dto.usageEntitlement).toBeUndefined();
    });

    test('Dimensions without tiers do not gain a tiers field when read back', () => {
        const entity = DimensionEntity.dbModelToEntity({
            _value: 'Requests',
            businessID: 'fakeBusinessID',
            dimensionId: 'fakeDimensionId',
            typeofDimension: 'numerical',
            dimensionUnit: countBasedUnits['count-based'],
            dimensionUnitType: 'count',
            aggregationInterval: aggregationInterval.day,
            aggregationMethod: aggregationMethod.sum,
            priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf', price: '0.4' }]),
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
        });
        expect(entity.numerical.tiers).toBeUndefined();
        const dto = new CreateDimensionDto(entity);
        expect(dto.tiers).toBeUndefined();
        expect(dto.consumptionPrice).toEqual('0.4');
    });

    test('Creating a dimension with invalid tiers is rejected', async () => {
        await expect(
            service.create(
                {
                    ...tieredDimensionDto(),
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: '500', unitPrice: '1' },
                    ],
                } as unknown as CreateDimensionDto,
                'fakeSubject',
            ),
        ).rejects.toThrow();
        await expect(
            service.create(
                {
                    ...tieredDimensionDto(),
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: 'inf' },
                    ],
                } as unknown as CreateDimensionDto,
                'fakeSubject',
            ),
        ).rejects.toThrow();
    });

    test('Creating a dimension with valid tiers persists them', async () => {
        const loadPoints = jest.fn();
        //eslint-disable-next-line
        //@ts-ignore
        service.InfluxService.loadPoints = loadPoints;
        //eslint-disable-next-line
        //@ts-ignore
        service.InfluxService.getPoint = (measurement: string) => new Point(measurement);
        const { dimensionId } = await service.create(tieredDimensionDto(), 'fakeSubject');
        expect(dimensionId).toEqual(expect.any(String));
        expect(loadPoints).toBeCalledTimes(1);
        const [[, , points]] = loadPoints.mock.calls;
        expect(points[0].toLineProtocol()).toContain('tierPosition');
    });

    test('Updating a dimension replaces its tiers and can clear them with null', async () => {
        const loadPoints = jest.fn();
        //eslint-disable-next-line
        //@ts-ignore
        service.InfluxService.loadPoints = loadPoints;
        //eslint-disable-next-line
        //@ts-ignore
        service.InfluxService.getPoint = (measurement: string) => new Point(measurement);
        jest.spyOn(service, 'findOne').mockImplementation(async () => ({
            message: 'Found Dimension',
            data: [
                {
                    dimensionId: 'fakeDimensionId',
                    ...tieredDimensionDto(),
                },
            ],
        }));
        const replacementTiers: DimensionTier[] = [
            { tierPosition: '1', upperBound: '10', unitPrice: '1' },
            { tierPosition: '2', upperBound: 'inf', unitPrice: '0.5' },
        ];
        await service.update(
            { dimensionId: 'fakeDimensionId', businessID: 'fakeBusinessID', tiers: replacementTiers },
            'fakeSubject',
        );
        const [[, , points]] = loadPoints.mock.calls;
        expect(points[0].toLineProtocol()).toContain(JSON.stringify(replacementTiers).slice(1, 20));
        loadPoints.mockClear();

        await service.update(
            { dimensionId: 'fakeDimensionId', businessID: 'fakeBusinessID', tiers: null },
            'fakeSubject',
        );
        const [[, , pointsWithoutTiers]] = loadPoints.mock.calls;
        expect(pointsWithoutTiers[0].toLineProtocol()).not.toContain('tiers=');
    });

    test('Updating a dimension with invalid tiers is rejected', async () => {
        jest.spyOn(service, 'findOne').mockImplementation(async () => ({
            message: 'Found Dimension',
            data: [{ dimensionId: 'fakeDimensionId', ...tieredDimensionDto() }],
        }));
        await expect(
            service.update(
                {
                    dimensionId: 'fakeDimensionId',
                    businessID: 'fakeBusinessID',
                    tiers: [{ tierPosition: '1', upperBound: 'zero' }],
                },
                'fakeSubject',
            ),
        ).rejects.toThrow();
    });

    test('Updating a tiered dimension with a consumption price is rejected', async () => {
        jest.spyOn(service, 'findOne').mockImplementation(async () => ({
            message: 'Found Dimension',
            data: [{ dimensionId: 'fakeDimensionId', ...tieredDimensionDto() }],
        }));
        await expect(
            service.update(
                { dimensionId: 'fakeDimensionId', businessID: 'fakeBusinessID', consumptionPrice: '2' },
                'fakeSubject',
            ),
        ).rejects.toThrow();
    });
});

import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    DimensionTier,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from '../../dimensions/dto/read-dimension.dto.js';
import { Billing } from '../../billing/entities/billing.entity.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const dimensionId = '123';

const tiers: DimensionTier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000' },
    { tierPosition: '2', upperBound: '5000', tierName: 'Next 4000', unitPrice: '0.05' },
    { tierPosition: '3', upperBound: 'inf', tierName: 'Remaining', unitPrice: '0.03' },
];

const tieredDimension = (overrides: Partial<ReadDimensionResponseData> = {}): ReadDimensionResponseData =>
    ({
        dimensionId,
        dimensionName: 'Requests',
        usageIncrement: '1',
        rounding: roundingEnum.ceiling,
        aggregationInterval: aggregationInterval.day,
        aggregationMethod: aggregationMethod.sum,
        consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
        tiers,
        ...overrides,
    }) as ReadDimensionResponseData;

describe('Volume based pricing tiers', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let usageOffering: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;
    let settings: ReadSettingsResponseData;
    const businessID = 'fakeBusinessID';
    const customerId = 'fakeCustomerID';

    const usageOf = (value: string) =>
        ({
            message: 'fake',
            data: [
                {
                    dimensionId,
                    usage: [
                        {
                            startTime: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
                            endTime: DatetimeUtils.endOfDay(new Date()).toISOString(),
                            value,
                        },
                    ],
                },
            ],
        }) as ReadCustomerUsageData;

    const getLineItems = async (dimension: ReadDimensionResponseData) => {
        const offeringInstance = Offering.getInstance(
            { ...usageOffering, dimensions: [dimension] },
            customerId,
            businessID,
            invoicesService,
            settings,
            schedulerService,
            customerService,
        );
        const lineItems = await Offering.getLineItemsForUsage({
            startDate: DatetimeUtils.beginningOfDay(new Date()),
            endDate: DatetimeUtils.endOfDay(new Date()),
            customer,
            lineItems: new InvoiceLineItems(),
            businessID,
            customerId,
            customerService,
            dimensions: [dimension],
            offeringInstance,
        });
        return lineItems.getLineItems();
    };

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({ invoiceId: '123', message: 'fake' }));
    });

    beforeEach(() => {
        jest.useFakeTimers('modern').setSystemTime(new Date('2023-08-16'));
        settings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
        usageOffering = {
            offeringId: '123',
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            dimensions: [],
            billingCycle: ValidBillingCycles.monthly,
        };
        customer = {
            customerId,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            offering: usageOffering,
            businessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
        };
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.useRealTimers();
    });

    describe('Billing.allocateUsageToTiers', () => {
        test('Usage is allocated across the inclusive bounds of every tier', () => {
            expect(Billing.allocateUsageToTiers({ totalUsage: 6000, tiers })).toEqual([
                expect.objectContaining({ usage: 1000, tier: tiers[0] }),
                expect.objectContaining({ usage: 4000, tier: tiers[1] }),
                expect.objectContaining({ usage: 1000, tier: tiers[2] }),
            ]);
        });

        test('Only the consumed tiers are returned', () => {
            expect(Billing.allocateUsageToTiers({ totalUsage: 1000, tiers })).toEqual([
                expect.objectContaining({ usage: 1000, tier: tiers[0] }),
            ]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 1500, tiers })).toEqual([
                expect.objectContaining({ usage: 1000, tier: tiers[0] }),
                expect.objectContaining({ usage: 500, tier: tiers[1] }),
            ]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 0, tiers })).toEqual([]);
        });

        test('Tiers are allocated in the numerical order of their tier position', () => {
            const unorderedTiers: DimensionTier[] = [
                { tierPosition: '10', upperBound: 'inf', unitPrice: '0.03' },
                { tierPosition: '2', upperBound: '5000', unitPrice: '0.05' },
                { tierPosition: '1', upperBound: '1000' },
            ];
            expect(Billing.allocateUsageToTiers({ totalUsage: 5500, tiers: unorderedTiers })).toEqual([
                expect.objectContaining({ usage: 1000, tier: unorderedTiers[2] }),
                expect.objectContaining({ usage: 4000, tier: unorderedTiers[1] }),
                expect.objectContaining({ usage: 500, tier: unorderedTiers[0] }),
            ]);
        });
    });

    describe('Invoice line items', () => {
        test('A line item is created for every consumed tier, the free first tier is priced at 0', async () => {
            customerService.findUsageForCustomer = jest.fn().mockResolvedValue(usageOf('6000'));
            expect(await getLineItems(tieredDimension())).toEqual([
                new InvoiceLineItem('Requests - foobar - First 1000', 1000, 0),
                new InvoiceLineItem('Requests - foobar - Next 4000', 4000, 0.05),
                new InvoiceLineItem('Requests - foobar - Remaining', 1000, 0.03),
            ]);
